"""Canonical JSON bytes, sha256 digests, and positional ID minting.

Isolation-clean: stdlib only. `canonical_bytes` sorts *object keys*
(`sort_keys=True`); it never reorders a JSON array. That distinction is what
makes D8's order-sensitive `strategy_config` shape work: encoding declared
variable order as an array of `[name, domain]` pairs (never a `{name:
domain}` object) keeps the order-bearing bytes order-sensitive, because
`sort_keys` cannot touch array element order.
"""
from __future__ import annotations

import hashlib
import json
from typing import Any


def canonical_bytes(obj: Any) -> bytes:
    """Deterministic JSON bytes: sorted object keys, no incidental whitespace."""
    return json.dumps(obj, sort_keys=True, separators=(",", ":")).encode("utf-8")


def digest_of(obj: Any) -> str:
    return hashlib.sha256(canonical_bytes(obj)).hexdigest()


def mint_proposal_id(study_id: str, index: int) -> str:
    return f"{study_id}:p{index:04d}"


def mint_candidate_id(study_id: str, index: int) -> str:
    return f"{study_id}:c{index:04d}"


def mint_attempt_id(candidate_id: str, attempt_number: int) -> str:
    return f"{candidate_id}:a{attempt_number}"

"""Study-layer exceptions.

Isolation-clean: stdlib only.
"""
from __future__ import annotations


class IncompatibleStore(Exception):
    """Raised when opening a store whose bound compatibility fingerprints differ."""


class StudyLocked(Exception):
    """Raised when acquiring a runner lease that another runner still holds live."""


class StudyLeaseLost(Exception):
    """Raised when a fenced write finds the lease no longer held by this writer (D4/MF-1)."""


class StudyBridgeDefect(Exception):
    """Raised when the bridge produces an ENTRY_VALIDATION failure — a runner defect, never a case."""

    def __init__(self, failure) -> None:
        super().__init__(f"bridge produced an invalid entry model: {failure.cause}")
        self.failure = failure


class RetryableStoreError(Exception):
    """A transient store-I/O fault (staging/commit OSError, SQLite OperationalError)."""

"""Phase 2 subprocess helper: dump a fixed grid's proposal sequence as JSON.

Runnable as: python -m simkit.tests.study._grid_dump
"""
from __future__ import annotations

import json

from simkit.study.strategy import GridStrategy

STUDY_ID = "study-grid-pin"


def build_grid() -> GridStrategy:
    return GridStrategy(
        [
            ("plant_budget", [3000.0, 6000.0, 9000.0]),
            ("plant_width", [2.0, 3.0]),
        ]
    )


def main() -> int:
    proposals = list(build_grid().propose(STUDY_ID))
    print(json.dumps(proposals))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""Constraint report aggregator (S4 test-only generation).

Exact input schema: one REQUIRED field per concrete assertion — a missing
result is a schema failure, not a silent gap. Exists even for zero assertions.
"""

from pydantic import BaseModel
from simkit.config.schema import MultiOutput
from simkit.core.base import ModuleBase, ModuleResult

from wi014_s4.schemas.constraint_types import ConstraintEvaluation, ConstraintReport

EXPECTED_IDS = ('toy_plant__demo_plant__affordable',)


class ConstraintReportAggregatorInput(BaseModel):
    model_config = {"extra": "forbid"}

    toy_plant__demo_plant__affordable: ConstraintEvaluation


class ConstraintReportAggregatorOutput(MultiOutput):
    constraint_report: ConstraintReport


class ConstraintReportAggregatorModule(
    ModuleBase[ConstraintReportAggregatorInput, ConstraintReportAggregatorOutput]
):
    name: str = "constraint_report_aggregator"
    version: str = "s4-probe"

    CATALOG_FINGERPRINT = "659d0298caaa51ac4f4f9bee5ecde14d9ef929cf5c8ced3ca2e7857bce87d00f"

    def run(self, **evaluations) -> ModuleResult[ConstraintReportAggregatorOutput]:
        validated = ConstraintReportAggregatorInput(**evaluations)
        results = [getattr(validated, cid) for cid in EXPECTED_IDS]
        statuses = [r.status for r in results]
        if "violated" in statuses:
            headline = "violation"
        elif "indeterminate" in statuses:
            headline = "indeterminate"
        elif results:
            headline = "all_satisfied"
        else:
            headline = "not_assessed"
        return ModuleResult(
            data=ConstraintReportAggregatorOutput(
                constraint_report=ConstraintReport(
                    catalog_fingerprint=self.CATALOG_FINGERPRINT,
                    assessed_count=len(results),
                    headline=headline,
                    results=results,
                )
            )
        )
